    tt("close_main_menu", "The caller needs nothing else, thanks or says goodbye, declines what was offered, or wants a different transaction now"),
    tt("close_third_party", "The caller asks about another person's card or debt"),
    tt("close_language", "The caller does not speak Turkish"),
    tt("close_silence", "Third silence in a row (no answer at all three times)"),
