            vars['week_intro'] = s + ' Hesap kesim tarihinizi değiştirmek ister misiniz?'
            opts = [ORD[w] for w in (1, 2, 3, 4) if w != wk]
            vars['week_options'] = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Hesap kesim tarihinizi ayın ' + opts[0] + ', ' + opts[1] + ' ya da ' + opts[2] + ' haftasına alabilirim. Hangisini tercih edersiniz?'
            vars['week_allowed'] = ','.join(str(w) for w in (1, 2, 3, 4) if w != wk)
            vars['week_card_label'] = 'Sonu ' + digits(l4) + ' ile biten ' + (nm + ' kartınızın' if nm else 'kartınızın')
            vars['week_state'] = 'ok'
        result['data'] = {'week_state': vars.get('week_state')}
except Exception:
    vars['week_state'] = 'error'
'''

DECIDE_PRE = TRH + r'''
try:
    b = config.get('body') if isinstance(config.get('body'), dict) else {}
    w = re.sub(r'\D', '', str(b.get('new_week') or ''))[:1]
    vars['req_week'] = w
    vars['week_block'] = ''
    if w == str(vars.get('cur_week')):
        vars['week_block'] = 'current'
    elif w not in lst('week_allowed'):
        vars['week_block'] = 'not_offered'
    idx = str(vars.get('sel_idx') or '')
    config['body'] = env({'cardNumber': '' if vars['week_block'] else str(vars.get('card_' + idx) or ''),
                          'newStatementWeek': w, 'statementDay': int(fl(vars.get('cur_day')))})
except Exception:
    pass
'''

DECIDE_POST = TRH + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        blk = vars.get('week_block')
        if blk == 'current':
            result['data'] = {'ok': False, 'what_to_do_next': 'That is already the card\'s current week. Say: "Hesap kesim haftanız zaten bu hafta, bir değişiklik gerekmiyor." Then ask if they want another of the offered weeks.'}
        elif blk:
            result['data'] = {'ok': False, 'what_to_do_next': 'Only the offered weeks are possible (no days or dates). Say exactly: "' + str(vars.get('week_options')) + '" One try is used.'}
        else:
            b = ok_body(result)
            if b is None:
                vars['week_err'] = 'yes'
                result['data'] = {'ok': False, 'what_to_do_next': 'Service error. The call is handed over automatically.'}
            else:
                w = int(fl(vars.get('req_week')))
                nd, ndue = sdate(b.get('statementDate')), sdate(b.get('statementDueDate'))
                q = 'Yeni hesap kesim haftanız her ayın ' + ORD.get(w, str(w)) + ' haftası olacak. Yeni hesap kesim tarihiniz ' + nd + ', son ödeme tarihiniz ' + ndue + ' olacak.'
                if vars.get('week_joint'):
                    q += ' ' + vars.get('week_joint')
                q += ' Onaylıyor musunuz?'
                vars['preview_week'] = str(w)
                vars['confirm_text'] = q
                vars['week_done_text'] = str(vars.get('week_card_label')) + ' hesap kesim haftası her ayın ' + ORD.get(w, str(w)) + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + nd + ', son ödeme tarihiniz ' + ndue + '.'
                result['data'] = {'ok': True, 'what_to_do_next': 'Say exactly, word for word: "' + q + '" Then wait. Only a clear evet confirms.'}
except Exception:
    vars['week_err'] = 'yes'
'''

CHANGE_PRE = TRH + r'''
try:
    b = config.get('body') if isinstance(config.get('body'), dict) else {}
    w = re.sub(r'\D', '', str(b.get('new_week') or ''))[:1]
    pw = str(vars.get('preview_week') or '')
    vars['change_block'] = '' if (pw and w == pw and str(vars.get('week_done')) != 'yes') else 'yes'
    idx = str(vars.get('sel_idx') or '')
    config['body'] = env({'cardNumber': '' if vars['change_block'] else str(vars.get('card_' + idx) or ''),
                          'newStatementWeek': pw or w, 'statementDay': int(fl(vars.get('cur_day')))})
except Exception:
    vars['change_block'] = 'yes'
'''

CHANGE_POST = TRH + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        if vars.get('change_block'):
            result['data'] = {'ok': False, 'what_to_do_next': 'Not allowed: preview_week must run first for this week and the caller must say a clear evet to its dates. Nothing was changed.'}
        else:
            b = ok_body(result)
            if b is not None and str(b.get('exitState') or 'OK').upper() == 'OK' and str(b.get('responseCode', 0)) in ('0', '0.0'):
                vars['week_done'] = 'yes'
                result['data'] = {'ok': True, 'what_to_do_next': 'Changed. The result is spoken automatically.'}
            else:
                vars['week_err'] = 'yes'
                result['data'] = {'ok': False, 'what_to_do_next': 'NOT changed. Never say it was changed. The call is handed over automatically.'}
except Exception:
    vars['week_err'] = 'yes'
'''

# ------------------------------------------------------------------ routing code
AFTER_BAL = TRH + r'''
try:
    vars['bal_new'] = 'no'
    r = lst('read_idx')
    s = str(vars.get('sel_idx') or '')
    if s and s not in r:
        r.append(s)
    vars['read_idx'] = ','.join(r)
except Exception:
    pass
'''

COMPOSE = TRH + r'''
try:
    reading = str(vars.get('reading_text') or '')
    rem = [k for k in lst('elig_idx') if k not in lst('read_idx')]
    es = str(vars.get('email_state') or '')
    vars['route'] = 'menu'
    if rem:
        vars['tail_kind'] = 'other_card'
        vars['menu_speech'] = reading + ' Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    elif vars.get('last_nodebt') == 'yes':
        vars['route'] = 'end'
        vars['close_outcome'] = 'main_menu_no_debt'
        vars['farewell'] = reading + ' Sizi ana menüye yönlendiriyorum.'
    elif es == 'error':
        vars['route'] = 'end'
        vars['close_outcome'] = 'agent_service_error'
        vars['farewell'] = reading + ' Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
    else:
        vars['tail_kind'] = 'offer'
        if es == 'ok':
            vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
        else:
            vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim.'
        vars['menu_speech'] = reading + ' ' + vars['offer_text']
except Exception:
    vars['route'] = 'menu'
    vars['menu_speech'] = str(vars.get('reading_text') or '')
'''

OFFER_ROUTE = TRH + r'''
try:
    es = str(vars.get('email_state') or '')
    vars['route'] = 'menu'
    if vars.get('last_nodebt') == 'yes':
        vars['route'] = 'end'
        vars['close_outcome'] = 'main_menu'
        vars['farewell'] = 'Sizi ana menüye yönlendiriyorum.'
    elif es == 'error':
        vars['route'] = 'end'
        vars['close_outcome'] = 'agent_service_error'
        vars['farewell'] = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
    else:
        vars['tail_kind'] = 'offer'
        vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.' if es == 'ok' else 'Hesap kesim tarihinizi değiştirebilirim.'
        vars['menu_speech'] = vars['offer_text']
except Exception:
    vars['route'] = 'menu'
'''

EMAIL_ROUTE = TRH + r'''
try:
    es = str(vars.get('email_state') or '')
    if es == 'ok':
        vars['route'] = 'email'
    elif es == 'error':
        vars['route'] = 'end'
        vars['close_outcome'] = 'agent_service_error'
