                        "spoken_digits": {"type": "string", "description": "All digits the caller said about the card, as digits only; empty if none", "default": "{{sd}}"}},
                       ["card_index"], pre=BAL_PRE, post=BAL_POST, path="cards.balance", timeout_ms=20000)
get_balance = api_tool(BASE, "get_balance", "Get the debt of the chosen card.", {}, pre=BAL_PRE, post=BAL_POST, path="cards.balance", retries=1, timeout_ms=20000)
get_cards = api_tool(BASE, "get_cards", "Get the caller's cards.", {}, pre=CARDS_PRE, post=CARDS_POST, path="cards.list", retries=1, timeout_ms=20000)
get_email = api_tool(BASE, "get_email", "Get the registered e-mail.", {}, pre=EMAIL_PRE, post=EMAIL_POST, path="contact.email.get", retries=1, timeout_ms=20000)
send_statement = api_tool(BASE, "send_statement", "CALL it only after the caller clearly said yes to sending the latest statement to the registered address read to them.",
                          {"confirm": {"type": "string", "description": "always yes", "default": "yes"}}, pre=SEND_PRE, post=SEND_POST,
                          path="statement.pdf.send", timeout_ms=20000)
get_week = api_tool(BASE, "get_week", "Get the statement week.", {}, pre=WEEKGET_PRE, post=WEEKGET_POST, path="statement.week.get", retries=1, timeout_ms=20000)
preview_week = api_tool(BASE, "preview_week", "CALL it when the caller picks one of the offered weeks. Gets the new dates; changes nothing.",
                        {"new_week": {"type": "string", "description": "Chosen week number 1-4", "enum": ["1", "2", "3", "4"], "default": "{{nw}}"}},
                        ["new_week"], pre=DECIDE_PRE, post=DECIDE_POST, path="statement.week.decide", timeout_ms=20000)
change_week = api_tool(BASE, "change_week", "CALL it only after preview_week and a clear 'evet' to the dates read. Changes the statement week.",
                       {"new_week": {"type": "string", "description": "The same week as in preview_week", "enum": ["1", "2", "3", "4"], "default": "{{nw2}}"}},
