    {"target_node": "close_no_card", "description": "404 warning", "condition": cond_vals("get_cards_status_code", ["404"])},
])
N["fetch_balance"] = api_node("fetch_balance", get_balance, "close_service_error", extra_transitions=[
    {"target_node": "after_balance", "description": "balance read", "condition": cond_vals("bal_state", ["ok"])},
])
SEL_TRANS = [
    {"target_node": "after_balance", "description": "card chosen and balance read", "condition": cond_vals("bal_new", ["yes"])},
    {"target_node": "close_service_error", "description": "balance service failed", "condition": cond_vals("bal_state", ["error"])},
] + COMMON
N["select_card"] = conv_node("select_card", T_SELECT, on_enter_text="{{select_question}}", tools=[choose_card],
                             transitions=SEL_TRANS, max_turns=14, max_turn_target="close_tries")
N["select_again"] = conv_node("select_again", T_SELECT, on_enter_prompt=(
